class Solution {
  public int alternatingXOR(int[] nums, int target1, int target2) {
    final long MOD = 1_000_000_007L;
    int size = 1 << 17;
    long[] sumB = new long[size], sumA = new long[size];
    sumB[0] = 1;
    int prefix = 0;
    long dpA = 0, dpB = 0;
    for (int x : nums) {
      prefix ^= x;
      dpA = sumB[prefix ^ target1];
      dpB = sumA[prefix ^ target2];
      sumA[prefix] = (sumA[prefix] + dpA) % MOD;
      sumB[prefix] = (sumB[prefix] + dpB) % MOD;
    }
    return (int) ((dpA + dpB) % MOD);
  }
}
